drop policy "files read" on public.files;
create policy "files read" on public.files for select to authenticated using(can_read_file(id) and _msg_file_row_ok(id));
drop policy if exists "rikaz files read" on storage.objects;
create policy "rikaz files read" on storage.objects for select to authenticated using(bucket_id='rikaz-files' and exists(select 1 from public.files f where f.storage_path=storage.objects.name and public.can_read_file(f.id)));
alter table public.co_materials add column author_name text not null default '', add column author_role text not null default '', add column author_branch text not null default '';
create or replace function public._co_material_guard() returns trigger language plpgsql set search_path=public as $$ begin if new.category not in ('activities','teaching','worksheets','notes','summaries','courses') or length(trim(new.title))<2 or length(new.title)>200 or length(new.description)>10000 then raise exception 'بيانات المادة غير صالحة'; end if; if tg_op='UPDATE' and (new.id,new.org_id,new.school_id,new.author,new.created_at,new.author_name,new.author_role,new.author_branch) is distinct from (old.id,old.org_id,old.school_id,old.author,old.created_at,old.author_name,old.author_role,old.author_branch) then raise exception 'لا يسمح بنقل ملكية أو نطاق المادة'; end if; if tg_op='INSERT' then if not _co_ok(new.org_id) or not exists(select 1 from user_active_context c where c.user_id=auth.uid() and c.org_id=new.org_id and (c.school_id=new.school_id or c.role='org_owner')) then raise exception 'فرع المشاركة غير مصرح'; end if; new.author_name:=(select full_name from profiles where id=auth.uid()); new.author_role:=(select role from user_active_context where user_id=auth.uid()); new.author_branch:=(select name from schools where id=new.school_id); end if; new.updated_at:=now(); return new; end $$;
create or replace function private._co_material_cleanup() returns trigger language plpgsql security definer set search_path=public as $$ begin update files set source_type='cleanup_due' where source_type='co_material' and source_id=old.id; insert into comm_audit(org_id,school_id,action,details) values(old.org_id,old.school_id,'co_material_delete',jsonb_build_object('material_id',old.id,'actor',auth.uid())); return old; end $$;
revoke all on function private._co_material_cleanup() from public,anon,authenticated;
create trigger co_material_cleanup after delete on public.co_materials for each row execute function private._co_material_cleanup();